const input = $input.first()?.json ?? {};
const body = input.body ?? input;

return [{
  json: {
    config: {
      companyName: body.companyName || 'ABM Solutions Demo',
      senderName: body.senderName || 'Demo Sender',
      senderEmail: body.senderEmail || 'demo@example.com',
      slackWebhookUrl: body.slackWebhookUrl || 'REPLACE_WITH_SLACK_WEBHOOK_URL',
      hubspotToken: body.hubspotToken || 'REPLACE_WITH_HUBSPOT_PRIVATE_APP_TOKEN',
      openAiApiKey: body.openAiApiKey || 'REPLACE_WITH_OPENAI_API_KEY',
      demoMode: body.demoMode !== false
    },
    payload: body
  }
}];

const d=$input.first().json,t=d.ticket,text=`${t.subject} ${t.message}`.toLowerCase();
let category='general';
if(/webhook|api|integration|workflow|error|trigger/.test(text)) category='technical';
else if(/invoice|billing|charge|refund/.test(text)) category='billing';
else if(/password|login|access/.test(text)) category='access';
const urgent=/blocking|urgent|down|cannot|can't|failed|twice/.test(text);
const sentiment=/frustrated|angry|unacceptable|blocking/.test(text)?'negative':'neutral';
return [{json:{...d,triage:{category,urgent,sentiment,priority:urgent?'high':'normal'}}}];

const d=$input.first().json,t=d.ticket,q=d.triage;
const kb={
 technical:'Please confirm the workflow is active, use the production webhook URL, and verify the request method matches the Webhook node. Then review the latest execution for an error.',
 billing:'Please share the invoice number or charge date so the billing record can be reviewed.',
 access:'Please use the password reset flow and confirm that the account email matches the invited address.',
 general:'Please provide the exact steps, expected outcome, and any error message.'
};
const escalate=q.urgent||q.sentiment==='negative';
return [{json:{...d,result:{ticketId:t.id,category:q.category,priority:q.priority,escalate,response:`Hi ${t.customer},\n\nThanks for reporting this. ${kb[q.category]}\n\n${escalate?'I have also flagged this for priority human review.':'Reply with the requested details and we will continue troubleshooting.'}\n\nBest,\nSupport Team`,recommendedOwner:escalate?'Senior Support':'Support Queue'}}}];
